#if UNITY_EDITOR
using System.Collections.Generic;
using System.IO;
using System.Text;
using UnityEditor;
using UnityEngine;
using Logger = HelloDev.Logging.Logger;

namespace HelloDev.UI.Default.Editor
{
    public static class ColorIdGenerator
    {        private const string DefaultOutputPath = "Assets/HelloDev/UI/Generated/ColorIds.cs";
        private const string DefaultNamespace = "HelloDev.UI.Default";
n        public static void GenerateForDatabase(ColorDatabase_SO db, string outputPath = null, string namespaceName = null)        {            if (db == null)            {                Logger.LogError("UI", "[ColorIdGenerator] ColorDatabase_SO is null.");                return;            }            string path = string.IsNullOrWhiteSpace(outputPath) ? DefaultOutputPath : outputPath;            string ns = string.IsNullOrWhiteSpace(namespaceName) ? DefaultNamespace : namespaceName;            EnsureDirectoryExists(path);            var sb = new StringBuilder();            sb.AppendLine("// <auto-generated>");            sb.AppendLine("// Generated by ColorIdGenerator from ColorDatabase_SO.");            sb.AppendLine("// Do not edit manually.");            sb.AppendLine("// </auto-generated>");            sb.AppendLine();            sb.AppendLine($"namespace {ns}");            sb.AppendLine("{");            var usedIdentifiers = new HashSet<string>();            // ColorIds            sb.AppendLine("    public static class ColorIds");            sb.AppendLine("    {");            foreach (var slot in db.Slots)            {                if (string.IsNullOrEmpty(slot.Id) || string.IsNullOrEmpty(slot.Name)) continue;                string identifier = SanitizeIdentifier(slot.Name);                if (!usedIdentifiers.Add(identifier))                {                    Logger.LogWarning("UI", $"[ColorIdGenerator] Duplicate identifier '{identifier}' from Slot '{slot.Name}'. Skipping.");                    continue;                }                sb.AppendLine($"        public const string {identifier} = \"{slot.Id}\";");            }            sb.AppendLine("    }");            sb.AppendLine();            // ThemeIds            sb.AppendLine("    public static class ThemeIds");            sb.AppendLine("    {");            usedIdentifiers.Clear();            foreach (var theme in db.Themes)            {                if (string.IsNullOrEmpty(theme.Id) || string.IsNullOrEmpty(theme.DisplayName)) continue;                string identifier = SanitizeIdentifier(theme.DisplayName);                if (!usedIdentifiers.Add(identifier))                {                    Logger.LogWarning("UI", $"[ColorIdGenerator] Duplicate identifier '{identifier}' from Theme '{theme.DisplayName}'. Skipping.");                    continue;                }                sb.AppendLine($"        public const string {identifier} = \"{theme.Id}\";");            }            sb.AppendLine("    }");            sb.AppendLine();            // DatabaseKeys            sb.AppendLine("    public static class DatabaseKeys");            sb.AppendLine("    {");            string dbKeyIdentifier = SanitizeIdentifier(db.name + "_KEY");            sb.AppendLine($"        public const string {dbKeyIdentifier} = \"{db.name}\";");            sb.AppendLine("    }");            sb.AppendLine("}");            File.WriteAllText(path, sb.ToString());            AssetDatabase.Refresh();            Logger.Log("UI", $"[ColorIdGenerator] Generated constants at {path}");        }        private static void EnsureDirectoryExists(string filePath)        {            string directory = Path.GetDirectoryName(filePath);            if (!string.IsNullOrEmpty(directory) && !Directory.Exists(directory))                Directory.CreateDirectory(directory);        }        private static string SanitizeIdentifier(string value)        {            var sb = new StringBuilder(value.Length);            foreach (char c in value)            {                if (char.IsLetterOrDigit(c) || c == '_')                    sb.Append(c);                else                    sb.Append('_');            }            if (sb.Length > 0 && char.IsDigit(sb[0]))                sb.Insert(0, '_');            return sb.ToString();        }    }}#endif
